import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding);
"""
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline.h>
constexpr int TILE_OH = 8;
constexpr int TILE_OW = 16;
constexpr int TILE_CO = 32;
constexpr int BLOCK_THREADS = 256;
constexpr int RT_H = 2;
constexpr int RT_W = 2;
constexpr int RT_C = 4;
// Optimization (improved shared-memory reuse): sliding-window register cache.
// When instantiated with compile-time KH/KW/stride, the input window that
// feeds both RT_W outputs (spaced strideW apart) is staged from shared
// memory into registers exactly once per (ci, kh) row and then reused for
// every kernel tap, instead of re-reading the overlapped shared locations
// on each tap. The <0, 0, 0> instantiation keeps the generic runtime-loop
// path so arbitrary shapes remain correct.
// Async (cp.async-capable) weight-chunk loader used to stage the
// per-output-channel weight tiles through a single shared-memory buffer;
// chunk k+1 is issued right after chunk k has been fully consumed and the
// prologue load overlaps the input-tile staging. Falls back to plain
// copies when 16B alignment is not guaranteed or when the architecture
// does not support asynchronous copies.
__device__ __forceinline__ void load_weight_chunk_async(
    const float* __restrict__ w, float* __restrict__ sh_w,
    int co0, int M, int wElemsPerCo, int KHKW, int KW,
    int wChunkElems, int tid, int nthreads, bool vecW)
{
    if (vecW) {
        const float4* w4 = reinterpret_cast<const float4*>(w + (size_t)co0 * wElemsPerCo);
        float4* sh_w4 = reinterpret_cast<float4*>(sh_w);
        const int wVecElems = wChunkElems >> 2;
        for (int idx = tid; idx < wVecElems; idx += nthreads) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            __pipeline_memcpy_async(&sh_w4[idx], &w4[idx], 16);
#else
            sh_w4[idx] = w4[idx];
#endif
        }
    } else {
        for (int idx = tid; idx < wChunkElems; idx += nthreads) {
            const int coL = idx / wElemsPerCo;
            const int rem = idx - coL * wElemsPerCo;
            const int ci = rem / KHKW;
            const int krem = rem - ci * KHKW;
            const int kh = krem / KW;
            const int kw = krem - kh * KW;
            const int co = co0 + coL;
            float v = 0.0f;
            if (co < M) {
                v = w[(size_t)co * wElemsPerCo + ci * KHKW + krem];
            }
            sh_w[idx] = v;
        }
    }
}
template <int T_KH, int T_KW, int T_STRIDE>
__global__ void __launch_bounds__(BLOCK_THREADS) conv2d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int C, int H, int W,
    int M, int KHr, int KWr,
    int strideHr, int strideWr,
    int padH, int padW,
    int OH, int OW,
    int inTileH, int inTileW)
{
    const int KH = (T_KH > 0) ? T_KH : KHr;
    const int KW = (T_KW > 0) ? T_KW : KWr;
    const int strideH = (T_STRIDE > 0) ? T_STRIDE : strideHr;
    const int strideW = (T_STRIDE > 0) ? T_STRIDE : strideWr;
    const int tid = threadIdx.x;
    const int n = blockIdx.z;
    const int oh0 = blockIdx.y * TILE_OH;
    const int ow0 = blockIdx.x * TILE_OW;
    extern __shared__ float smem[];
    const int inElems = C * inTileH * inTileW;
    const int inElemsAligned = (inElems + 3) & ~3;
    const int wElemsPerCo = C * KH * KW;
    float* sh_in = smem;
    float* sh_w = smem + inElemsAligned;
    const int wChunkElems = TILE_CO * wElemsPerCo;
    const int wChunkElemsAligned = (wChunkElems + 3) & ~3;
    const int nChunks = (M + TILE_CO - 1) / TILE_CO;
    const int inBaseH = oh0 * strideH - padH;
    const int inBaseW = ow0 * strideW - padW;
    // Double-buffered weight pipeline: prefetch chunk 0 and chunk 1 up
    // front so the global weight loads for chunk k+1 overlap the compute
    // of chunk k. Buffers alternate by chunk parity; a chunk buffer is
    // only refilled after a __syncthreads() proves all threads consumed it.
    {
        const bool vecW0 = ((wChunkElems & 3) == 0) && (TILE_CO <= M);
        load_weight_chunk_async(w, sh_w, 0, M, wElemsPerCo, KH * KW, KW,
                                wChunkElems, tid, blockDim.x, vecW0);
        __pipeline_commit();
        if (1 < nChunks) {
            const int coN = TILE_CO;
            const bool vecW1 = ((wChunkElems & 3) == 0) && (coN + TILE_CO <= M) &&
                               ((((size_t)coN * (size_t)wElemsPerCo) & 3) == 0);
            load_weight_chunk_async(w, sh_w + wChunkElemsAligned, coN, M,
                                    wElemsPerCo, KH * KW, KW, wChunkElems,
                                    tid, blockDim.x, vecW1);
            __pipeline_commit();
        }
    }
    for (int idx = tid; idx < inElems; idx += blockDim.x) {
        const int ci = idx / (inTileH * inTileW);
        const int rem = idx - ci * (inTileH * inTileW);
        const int ih = rem / inTileW;
        const int iw = rem - ih * inTileW;
        const int gh = inBaseH + ih;
        const int gw = inBaseW + iw;
        float v = 0.0f;
        if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
            v = x[((n * C + ci) * H + gh) * W + gw];
        }
        sh_in[idx] = v;
    }
    __syncthreads();
    // Register-blocked thread mapping: each thread computes
    // RT_H x RT_W spatial outputs for RT_C output channels,
    // so shared-memory values are reused across registers.
    const int G_W = TILE_OW / RT_W;
    const int G_C = TILE_CO / RT_C;
    const int th = tid / (G_W * G_C);
    const int remT = tid - th * (G_W * G_C);
    const int tw = remT / G_C;
    const int tc = remT - tw * G_C;
    const int ohL0 = th * RT_H;
    const int owL0 = tw * RT_W;
    const int coL0 = tc * RT_C;
    const int ohA = oh0 + ohL0;
    const int owA = ow0 + owL0;
    const int ihBase = ohL0 * strideH;
    const int iwBase = owL0 * strideW;
    for (int chunk = 0; chunk < nChunks; ++chunk) {
        // Keep the newer prefetched chunk in flight while waiting only for
        // the chunk needed by this iteration.
        if (chunk + 1 < nChunks) {
            __pipeline_wait_prior(1);
        } else {
            __pipeline_wait_prior(0);
        }
        __syncthreads();
        const int co0 = chunk * TILE_CO;
        const float* sh_wc = sh_w + (size_t)(chunk & 1) * wChunkElemsAligned;
        const int co0 = chunk * TILE_CO;
        const int coA = co0 + coL0;
        float bv[RT_C];
        #pragma unroll
        for (int c = 0; c < RT_C; ++c) {
            bv[c] = (coA + c < M) ? b[coA + c] : 0.0f;
        }
        float acc[RT_H][RT_W][RT_C];
        #pragma unroll
        for (int i = 0; i < RT_H; ++i) {
            #pragma unroll
            for (int j = 0; j < RT_W; ++j) {
                #pragma unroll
                for (int c = 0; c < RT_C; ++c) {
                    acc[i][j][c] = bv[c];
                }
            }
        }
        for (int ci = 0; ci < C; ++ci) {
            const float* sh_in_c = sh_in + ci * inTileH * inTileW;
            const float* sh_w0 = sh_wc + coL0 * wElemsPerCo + ci * KH * KW;
            const float* sh_w1 = sh_w0 + wElemsPerCo;
            const float* sh_w2 = sh_w1 + wElemsPerCo;
            const float* sh_w3 = sh_w2 + wElemsPerCo;
            if constexpr (T_KW > 0) {
                // Window spans taps [0, T_KW) for output 0 plus the same
                // taps shifted by T_STRIDE for output 1; all indices are
                // compile-time so r0/r1 stay in registers.
                constexpr int WIN = T_KW + T_STRIDE;
                for (int kh = 0; kh < T_KH; ++kh) {
                    const float* row0 = sh_in_c + (ihBase + kh) * inTileW + iwBase;
                    const float* row1 = row0 + T_STRIDE * inTileW;
                    const float* w0r = sh_w0 + kh * T_KW;
                    const float* w1r = sh_w1 + kh * T_KW;
                    const float* w2r = sh_w2 + kh * T_KW;
                    const float* w3r = sh_w3 + kh * T_KW;
                    float r0[WIN];
                    float r1[WIN];
                    #pragma unroll
                    for (int t = 0; t < WIN; ++t) {
                        r0[t] = row0[t];
                        r1[t] = row1[t];
                    }
                    #pragma unroll
                    for (int kw = 0; kw < T_KW; ++kw) {
                        const float a00 = r0[kw];
                        const float a01 = r0[kw + T_STRIDE];
                        const float a10 = r1[kw];
                        const float a11 = r1[kw + T_STRIDE];
                        const float w0 = w0r[kw];
                        const float w1 = w1r[kw];
                        const float w2 = w2r[kw];
                        const float w3 = w3r[kw];
                        acc[0][0][0] += a00 * w0;
                        acc[0][0][1] += a00 * w1;
                        acc[0][0][2] += a00 * w2;
                        acc[0][0][3] += a00 * w3;
                        acc[0][1][0] += a01 * w0;
                        acc[0][1][1] += a01 * w1;
                        acc[0][1][2] += a01 * w2;
                        acc[0][1][3] += a01 * w3;
                        acc[1][0][0] += a10 * w0;
                        acc[1][0][1] += a10 * w1;
                        acc[1][0][2] += a10 * w2;
                        acc[1][0][3] += a10 * w3;
                        acc[1][1][0] += a11 * w0;
                        acc[1][1][1] += a11 * w1;
                        acc[1][1][2] += a11 * w2;
                        acc[1][1][3] += a11 * w3;
                    }
                }
            } else {
                for (int kh = 0; kh < KH; ++kh) {
                    const float* row0 = sh_in_c + (ihBase + kh) * inTileW + iwBase;
                    const float* row1 = row0 + strideH * inTileW;
                    const float* w0r = sh_w0 + kh * KW;
                    const float* w1r = sh_w1 + kh * KW;
                    const float* w2r = sh_w2 + kh * KW;
                    const float* w3r = sh_w3 + kh * KW;
                    #pragma unroll 4
                    for (int kw = 0; kw < KW; ++kw) {
                        const float a00 = row0[kw];
                        const float a01 = row0[kw + strideW];
                        const float a10 = row1[kw];
                        const float a11 = row1[kw + strideW];
                        const float w0 = w0r[kw];
                        const float w1 = w1r[kw];
                        const float w2 = w2r[kw];
                        const float w3 = w3r[kw];
                        acc[0][0][0] += a00 * w0;
                        acc[0][0][1] += a00 * w1;
                        acc[0][0][2] += a00 * w2;
                        acc[0][0][3] += a00 * w3;
                        acc[0][1][0] += a01 * w0;
