            const int rem = idx - coL * wElemsPerCo;
            const int ci = rem / KHKW;
            const int krem = rem - ci * KHKW;
            const int kh = krem / KW;
            const int kw = krem - kh * KW;
            const int co = co0 + coL;
            float v = 0.0f;
            if (co < M) {
                v = w[(size_t)co * wElemsPerCo + ci * KHKW + krem];
            }
            sh_w[idx] = v;
        }
    }
}
template <int T_KH, int T_KW, int T_STRIDE>
__global__ void __launch_bounds__(BLOCK_THREADS) conv2d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int C, int H, int W,
    int M, int KHr, int KWr,
    int strideHr, int strideWr,
    int padH, int padW,
    int OH, int OW,
    int inTileH, int inTileW)
{
    const int KH = (T_KH > 0) ? T_KH : KHr;
    const int KW = (T_KW > 0) ? T_KW : KWr;
    const int strideH = (T_STRIDE > 0) ? T_STRIDE : strideHr;
    const int strideW = (T_STRIDE > 0) ? T_STRIDE : strideWr;
    const int tid = threadIdx.x;
    const int n = blockIdx.z;
    const int oh0 = blockIdx.y * TILE_OH;
    const int ow0 = blockIdx.x * TILE_OW;
    extern __shared__ float smem[];
    const int inTileWP = (inTileW + 3) & ~3;
    const int inElems = C * inTileH * inTileW;
    const int inElemsAligned = (C * inTileH * inTileWP + 3) & ~3;
    const int wElemsPerCo = C * KH * KW;
    float* sh_in = smem;
    float* sh_w = smem + inElemsAligned;
    const int inBaseH = oh0 * strideH - padH;
    const int inBaseW = ow0 * strideW - padW;
    // Prologue: asynchronously stage the first weight chunk so the global
    // weight loads overlap the input-tile staging below.
    {
        const int wChunkElems0 = TILE_CO * wElemsPerCo;
        const bool vecW0 = ((wChunkElems0 & 3) == 0) && (TILE_CO <= M);
        load_weight_chunk_async(w, sh_w, 0, M, wElemsPerCo, KH * KW, KW,
                                wChunkElems0, tid, blockDim.x, vecW0);
        __pipeline_commit();
    }
    for (int idx = tid; idx < inElems; idx += blockDim.x) {
        const int ci = idx / (inTileH * inTileW);
        const int rem = idx - ci * (inTileH * inTileW);
        const int ih = rem / inTileW;
        const int iw = rem - ih * inTileW;
        const int gh = inBaseH + ih;
        const int gw = inBaseW + iw;
        float v = 0.0f;
        if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
            v = x[((n * C + ci) * H + gh) * W + gw];
        }
        sh_in[(ci * inTileH + ih) * inTileWP + iw] = v;
    }
    __syncthreads();
    const int wChunkElems = TILE_CO * wElemsPerCo;
    const int nChunks = (M + TILE_CO - 1) / TILE_CO;
    // Register-blocked thread mapping: each thread computes
    // RT_H x RT_W spatial outputs for RT_C output channels,
    // so shared-memory values are reused across registers.
    const int G_W = TILE_OW / RT_W;
    const int G_C = TILE_CO / RT_C;
    const int th = tid / (G_W * G_C);
    const int remT = tid - th * (G_W * G_C);
    const int tw = remT / G_C;
    const int tc = remT - tw * G_C;
    const int ohL0 = th * RT_H;
    const int owL0 = tw * RT_W;
    const int coL0 = tc * RT_C;
    const int ohA = oh0 + ohL0;
    const int owA = ow0 + owL0;
    const int ihBase = ohL0 * strideH;
    const int iwBase = owL0 * strideW;
    for (int chunk = 0; chunk < nChunks; ++chunk) {
        // Wait for the weight chunk staged asynchronously for this iteration
        // (prologue for chunk 0, end of the previous iteration otherwise).
        __pipeline_wait_prior(0);
        __syncthreads();
        const int co0 = chunk * TILE_CO;
        const int coA = co0 + coL0;
        float bv[RT_C];
        #pragma unroll
        for (int c = 0; c < RT_C; ++c) {
            bv[c] = (coA + c < M) ? b[coA + c] : 0.0f;
        }
        float acc[RT_H][RT_W][RT_C];
        #pragma unroll
        for (int i = 0; i < RT_H; ++i) {
            #pragma unroll
            for (int j = 0; j < RT_W; ++j) {
                #pragma unroll
                for (int c = 0; c < RT_C; ++c) {
                    acc[i][j][c] = bv[c];
                }
            }
        }
        for (int ci = 0; ci < C; ++ci) {
            const float* sh_in_c = sh_in + ci * inTileH * inTileWP;
            const float* sh_w0 = sh_w + coL0 * wElemsPerCo + ci * KH * KW;
            const float* sh_w1 = sh_w0 + wElemsPerCo;
            const float* sh_w2 = sh_w1 + wElemsPerCo;
            const float* sh_w3 = sh_w2 + wElemsPerCo;
            if constexpr (T_KW > 0) {
                // Window spans taps [0, T_KW) for output 0 plus the same
                // taps shifted by T_STRIDE for output 1; all indices are
                // compile-time so r0/r1 stay in registers.
                constexpr int WIN = T_KW + T_STRIDE;
                for (int kh = 0; kh < T_KH; ++kh) {
                    const float* row0 = sh_in_c + (ihBase + kh) * inTileWP + iwBase;
                    const float* row1 = row0 + T_STRIDE * inTileWP;
                    const float* w0r = sh_w0 + kh * T_KW;
                    const float* w1r = sh_w1 + kh * T_KW;
                    const float* w2r = sh_w2 + kh * T_KW;
                    const float* w3r = sh_w3 + kh * T_KW;
                    // Vectorized shared-memory window fetch: input-tile rows
                    // are padded to a multiple of 4 floats (inTileWP) and
                    // iwBase is a multiple of 8, so every 16-byte segment of
                    // the WIN-wide activation window is aligned and both rows
                    // are staged into registers with ld.shared.v4 instead of
                    // scalar shared loads.
                    float r0[WIN + 1];
                    float r1[WIN + 1];
                    #pragma unroll
                    for (int g = 0; g < (WIN + 3) / 4; ++g) {
                        const float4 x0 = *reinterpret_cast<const float4*>(row0 + 4 * g);
                        const float4 x1 = *reinterpret_cast<const float4*>(row1 + 4 * g);
                        r0[4 * g + 0] = x0.x;
                        r0[4 * g + 1] = x0.y;
                        r0[4 * g + 2] = x0.z;
                        r0[4 * g + 3] = x0.w;
                        r1[4 * g + 0] = x1.x;
                        r1[4 * g + 1] = x1.y;
                        r1[4 * g + 2] = x1.z;
                        r1[4 * g + 3] = x1.w;
                    }
                    #pragma unroll
                    for (int kw = 0; kw < T_KW; ++kw) {
                        const float a00 = r0[kw];
                        const float a01 = r0[kw + T_STRIDE];
                        const float a10 = r1[kw];
                        const float a11 = r1[kw + T_STRIDE];
                        const float w0 = w0r[kw];
                        const float w1 = w1r[kw];
                        const float w2 = w2r[kw];
                        const float w3 = w3r[kw];
                        acc[0][0][0] += a00 * w0;
                        acc[0][0][1] += a00 * w1;
                        acc[0][0][2] += a00 * w2;
                        acc[0][0][3] += a00 * w3;
                        acc[0][1][0] += a01 * w0;
                        acc[0][1][1] += a01 * w1;
                        acc[0][1][2] += a01 * w2;
                        acc[0][1][3] += a01 * w3;
                        acc[1][0][0] += a10 * w0;
                        acc[1][0][1] += a10 * w1;
                        acc[1][0][2] += a10 * w2;
                        acc[1][0][3] += a10 * w3;
                        acc[1][1][0] += a11 * w0;
                        acc[1][1][1] += a11 * w1;
                        acc[1][1][2] += a11 * w2;
                        acc[1][1][3] += a11 * w3;
                    }
                }
            } else {
                for (int kh = 0; kh < KH; ++kh) {
                    const float* row0 = sh_in_c + (ihBase + kh) * inTileWP + iwBase;
                    const float* row1 = row0 + strideH * inTileWP;
                    const float* w0r = sh_w0 + kh * KW;
                    const float* w1r = sh_w1 + kh * KW;
                    const float* w2r = sh_w2 + kh * KW;
                    const float* w3r = sh_w3 + kh * KW;
                    #pragma unroll 4
                    for (int kw = 0; kw < KW; ++kw) {
                        const float a00 = row0[kw];
                        const float a01 = row0[kw + strideW];
                        const float a10 = row1[kw];
                        const float a11 = row1[kw + strideW];
                        const float w0 = w0r[kw];
                        const float w1 = w1r[kw];
                        const float w2 = w2r[kw];
                        const float w3 = w3r[kw];
                        acc[0][0][0] += a00 * w0;
                        acc[0][0][1] += a00 * w1;
                        acc[0][0][2] += a00 * w2;
                        acc[0][0][3] += a00 * w3;
                        acc[0][1][0] += a01 * w0;
                        acc[0][1][1] += a01 * w1;
                        acc[0][1][2] += a01 * w2;
                        acc[0][1][3] += a01 * w3;
                        acc[1][0][0] += a10 * w0;
                        acc[1][0][1] += a10 * w1;
                        acc[1][0][2] += a10 * w2;
                        acc[1][0][3] += a10 * w3;
                        acc[1][1][0] += a11 * w0;
                        acc[1][1][1] += a11 * w1;
                        acc[1][1][2] += a11 * w2;
                        acc[1][1][3] += a11 * w3;
                    }
                }
            }
        }
        #pragma unroll
        for (int i = 0; i < RT_H; ++i) {
            const int oh = ohA + i;
            if (oh >= OH) continue;
            #pragma unroll
            for (int j = 0; j < RT_W; ++j) {
                const int ow = owA + j;
                if (ow >= OW) continue;
                #pragma unroll
                for (int c = 0; c < RT_C; ++c) {
                    const int co = coA + c;
                    if (co < M) {
                        y[((n * M + co) * OH + oh) * OW + ow] = acc[i][j][c];
                    }
                }
            }
        }
        __syncthreads();
        // Stage the next weight chunk into the single weight buffer. The
        // __syncthreads() above guarantees every thread has finished
        // reading sh_w before the (possibly asynchronous) copies begin.
        if (chunk + 1 < nChunks) {
            const int coN = (chunk + 1) * TILE_CO;
            const bool vecWN = ((wChunkElems & 3) == 0) && (coN + TILE_CO <= M) &&
                               ((((size_t)coN * (size_t)wElemsPerCo) & 3) == 0);
            load_weight_chunk_async(w, sh_w, coN, M, wElemsPerCo, KH * KW, KW,
                                    wChunkElems, tid, blockDim.x, vecWN);
            __pipeline_commit();
        }
    }
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 is supported");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "only float32 is supported");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "only float32 is supported");
    auto x = input.contiguous();
    auto w = weight.contiguous();
    auto b = bias.contiguous();
    const int N = (int)x.size(0);
    const int C = (int)x.size(1);
    const int H = (int)x.size(2);
    const int W = (int)x.size(3);
    const int M = (int)w.size(0);
    const int KH = (int)w.size(2);
    const int KW = (int)w.size(3);
    TORCH_CHECK((int)w.size(1) == C, "channel mismatch");
    const int strideH = (int)stride;
    const int strideW = (int)stride;
    const int padH = (int)padding;
    const int padW = (int)padding;
    const int OH = (H + 2 * padH - KH) / strideH + 1;
    const int OW = (W + 2 * padW - KW) / strideW + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output shape");
    auto y = torch::empty({N, M, OH, OW}, x.options());
    const int inTileH = (TILE_OH - 1) * strideH + KH;
    const int inTileW = (TILE_OW - 1) * strideW + KW;
    const int inTileWP = (inTileW + 3) & ~3;
    const int inElemsAligned = (C * inTileH * inTileWP + 3) & ~3;
    const int wChunkElems = TILE_CO * C * KH * KW;
    const int wChunkElemsAligned = (wChunkElems + 3) & ~3;
    const size_t smem_elems =
        (size_t)inElemsAligned + (size_t)wChunkElemsAligned;
    const size_t smem_bytes = smem_elems * sizeof(float);
    int dev = 0;
    C10_CUDA_CHECK(cudaGetDevice(&dev));
    int maxOptin = 0;
    C10_CUDA_CHECK(cudaDeviceGetAttribute(&maxOptin,
                    cudaDevAttrMaxSharedMemoryPerBlockOptin, dev));
    TORCH_CHECK(smem_bytes <= (size_t)maxOptin,
                "shared memory requirement too large: ", smem_bytes, " > ", maxOptin);
    const bool useFastPath = (KH == 11 && KW == 11 && strideH == 4 && strideW == 4);
    if (smem_bytes > 48 * 1024) {
        static bool configured = false;
        if (!configured) {
            C10_CUDA_CHECK(cudaFuncSetAttribute(conv2d_tiled_kernel<11, 11, 4>,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)smem_bytes));
            C10_CUDA_CHECK(cudaFuncSetAttribute(conv2d_tiled_kernel<0, 0, 0>,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)smem_bytes));
            configured = true;
        }
    }
    dim3 block(BLOCK_THREADS);
    dim3 grid((OW + TILE_OW - 1) / TILE_OW,
              (OH + TILE_OH - 1) / TILE_OH,
              N);
    auto stream = at::cuda::getCurrentCUDAStream();
    if (useFastPath) {
        conv2d_tiled_kernel<11, 11, 4><<<grid, block, smem_bytes, stream>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(), y.data_ptr<float>(),
            N, C, H, W, M, KH, KW, strideH, strideW, padH, padW, OH, OW, inTileH, inTileW);
    } else {
        conv2d_tiled_kernel<0, 0, 0><<<grid, block, smem_bytes, stream>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(), y.data_ptr<float>(),
            N, C, H, W, M, KH, KW, strideH, strideW, padH, padW, OH, OW, inTileH, inTileW);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
